fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Compute the alternating-sign prefix sum S(k)
    // S(k) = 0             if k <= 0
    //      =  k/2          if k is even
    //      = -(k+1)/2      if k is odd
    fn prefix_sum(k: i32) -> i32 {
        if k <= 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            - (k + 1) / 2
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            let l_minus_one = l as i32 - 1;
            let r32 = r as i32;
            let ans = prefix_sum(r32) - prefix_sum(l_minus_one);
            ans as i8
        })
        .collect()
}